'use strict';

// createLimiter accepts a positive integer Number concurrency, otherwise throws
// RangeError. It returns run(fn), which always returns a Promise. run rejects
// non-functions with TypeError. Queued functions start in submission order, with
// at most concurrency functions running. Values, promises, synchronous throws,
// and promise rejections settle only the corresponding run result; the limiter
// must remain usable afterward. Each function is invoked once, with no arguments.
function createLimiter(concurrency) {
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new RangeError('Concurrency must be a positive integer');
  }
  let active = 0;
  const queue = [];

  function drain() {
    while (active < concurrency && queue.length > 0) {
      const job = queue.shift();
      active += 1;
      Promise.resolve()
        .then(() => job.fn())
        .then(job.resolve, job.reject)
        .then(() => {
          active -= 1;
          drain();
        });
    }
  }

  return function run(fn) {
    if (typeof fn !== 'function') return Promise.reject(new TypeError('Task must be a function'));
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      drain();
    });
  };
}

module.exports = { createLimiter };

content.text:
I found and fixed the bug that made the tests hang. `node --test` now passes both tests, and the whole run takes about 0.2 seconds.

**Root cause:** in `src/limit.js`, when a task failed, the limiter rejected that task's result but never freed its slot. Successful tasks freed their slot and started the next queued task; failed ones didn't. So every failure permanently used up one slot. With a limit of 1, a single failure blocked everything queued after it, which is why the test "queued work still completes when a task rejects" hung until it timed out.

**Fix (`drain()` in `src/limit.js`):**
```js
Promise.resolve()
  .then(() => job.fn())
  .then(job.resolve, job.reject)
  .then(() => {
    active -= 1;
    drain();
  });
```
- **Slot freed in all cases:** the slot is now released and the next task started after the task finishes, whether it succeeds or fails. This also covers functions that throw synchronously, because that throw happens inside the promise chain.
- **Second issue fixed:** the old code passed each function an `undefined` argument, but the comment in the source says functions are called with no arguments. `() => job.fn()` now calls them with none.

`createLimiter` is still the CommonJS named export. I didn't change `test/` or `package.json` and didn't add any dependencies.
